  const typeDef = parse(new Source(body, name)).definitions[0];
  invariant(typeDef && typeDef.kind === Kind.OBJECT_TYPE_DEFINITION);
  const field = typeDef.fields && typeDef.fields[0];
  invariant(field);
  return field.type;
}

